function load() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return saved?.version === 8 ? saved : seedState();
  } catch { return seedState(); }
}
let state = load();
function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); updateShell(); }
function esc(value = "") { return String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
function person(id) { return state.employees.find(item => item.id === Number(id)); }
function current() { return person(state.currentEmployee) || state.employees.find(item => !item.archived) || state.employees[0]; }
function initials(value = "?") { return value.trim().split(/\s+/).slice(0, 2).map(word => word[0]).join("").toUpperCase(); }
function avatar(employee, className = "avatar") { return `<span class="${className}" aria-hidden="true">${esc(initials(employee?.name))}</span>`; }
function ids(values) { return [...values].map(Number).filter(Number.isFinite); }
function selected(form, name) { return ids([...form.elements[name].selectedOptions].map(option => option.value)); }
function safeDate(value) { const date = value ? new Date(value) : null; return date && !Number.isNaN(date.getTime()) ? date : null; }
function formatDate(value, options = { day: "2-digit", month: "2-digit", year: "numeric" }) { const date = safeDate(value); return date ? new Intl.DateTimeFormat("ru-RU", options).format(date) : "Не указано"; }
function formatDateTime(value) { const date = safeDate(value); return date ? new Intl.DateTimeFormat("ru-RU", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }).format(date) : "Не указано"; }
function age(value) { const birth = safeDate(value); if (!birth) return "не указан"; const today = new Date(); let years = today.getFullYear() - birth.getFullYear(); if (new Date(today.getFullYear(), birth.getMonth(), birth.getDate()) > today) years--; return `${years} лет`; }
function route() { const [name = "overview", id] = location.hash.slice(1).split("/"); return { name: name || "overview", id: Number(id) || null }; }
function toast(text) { const node = document.createElement("div"); node.className = "toast"; node.textContent = text; $("#toasts").append(node); setTimeout(() => node.remove(), 3200); if (state.settings.sound) beep(); }
function beep() { try { const ctx = new AudioContext(); const osc = ctx.createOscillator(); osc.connect(ctx.destination); osc.frequency.value = 560; osc.start(); osc.stop(ctx.currentTime + .07); } catch {} }
function header(kicker, title, text, action = "") { return `<section class="page-heading"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(text)}</p></div>${action}</section>`; }
function empty(text) { return `<div class="empty-state large"><strong>${esc(text)}</strong><span>Данные появятся после действий в этой демоверсии.</span></div>`; }
function demoNotice() { return `<div class="demo-banner"><strong>Демо без авторизации</strong><span>Профиль и права только имитируются в этом браузере. Не используйте реальные персональные данные.</span></div>`; }
function employeeOptions(selectedIds = [], exclude = []) { return state.employees.filter(e => !e.archived && !exclude.includes(e.id)).map(e => `<option value="${e.id}" ${selectedIds.includes(e.id) ? "selected" : ""}>${esc(e.name)} · ${esc(e.position)}</option>`).join(""); }
function addNotification(recipient, text, link) { state.notifications.unshift({ id: Date.now() + Math.random(), recipient: Number(recipient), text, link, createdAt: nowIso(), read: false }); }
function updateShell() {
  const mine = state.tasks.filter(t => t.workflow !== "Выполнено" && [...t.assignees, ...t.approvers].includes(state.currentEmployee)).length;
  const notices = state.notifications.filter(n => n.recipient === state.currentEmployee && !n.read).length;
  $("#taskCounter").textContent = mine;
  $("#noticeCounter").textContent = notices;
  $("#noticeBadge").textContent = notices;
  $("#noticeBadge").hidden = !notices;
  $("#profileAvatar").textContent = initials(current()?.name);
  document.documentElement.style.setProperty("--primary", state.settings.color || "#17365d");
  document.body.classList.toggle("dark-theme", state.settings.theme === "dark");
  $$('[data-leadership]').forEach(node => { node.hidden = current()?.role === "employee"; });
}
function closeMenu() { document.body.classList.remove("menu-open"); $("#menuButton").setAttribute("aria-expanded", "false"); }
function render() {
  const target = route();
  $$("[data-route]").forEach(link => link.classList.toggle("active", link.dataset.route === target.name));
  if (["analytics", "settings"].includes(target.name) && current().role === "employee") {
    app.innerHTML = header("Доступ ограничен", target.name === "analytics" ? "Аналитика" : "Настройки", "В полной версии доступ к разделу определяется серверными правами.") + demoNotice();
    updateShell(); closeMenu(); app.focus();
    return;
  }
  const views = { overview, tasks: () => tasks(false), completed: () => tasks(true), calendar, messages, employees, feed, analytics, settings };
  (views[target.name] || overview)();
  updateShell(); closeMenu(); app.focus();
  if (target.name === "tasks" && target.id) taskDialog(target.id);
}

function workSession() { return state.workdays.find(w => w.employee === state.currentEmployee && !w.endedAt); }
function elapsed(session) { if (!session) return "00:00:00"; const seconds = Math.max(0, Math.floor((Date.now() - new Date(session.startedAt)) / 1000)); return [seconds / 3600, seconds / 60 % 60, seconds % 60].map(value => String(Math.floor(value)).padStart(2, "0")).join(":"); }
function overview() {
  const me = current();
  const active = state.tasks.filter(t => t.workflow !== "Выполнено" && t.assignees.includes(me.id));
  const session = workSession();
  const today = localDate();
  const meetings = state.meetings.filter(m => m.date === today && m.status !== "Отменена" && m.participants.includes(me.id));
  app.innerHTML = demoNotice() + header(me.name, "Добрый день!", "Главное на сегодня в одном рабочем пространстве.") + `
    <section class="panel profile-strip">
      <div>${avatar(me, "employee-photo placeholder")}<div><span class="eyebrow">Выбранный демо-профиль</span><h2>${esc(me.name)}</h2><small>${esc(me.position)} · ${esc(me.status)}</small></div></div>
      <label class="field compact-field"><span>Статус</span><select data-action="quick-status">${statuses.map(s => `<option ${s === me.status ? "selected" : ""}>${s}</option>`).join("")}</select></label>
      <div class="timer-box"><span>Рабочий день</span><strong id="workTimer">${elapsed(session)}</strong><button class="button ${session ? "danger" : "secondary"}" data-action="toggle-workday">${session ? "Завершить" : "Начать"}</button></div>
    </section>
    <section class="stats-grid"><div class="stat-card"><span>Мои активные задачи</span><strong>${active.length}</strong><small>как исполнитель</small></div><div class="stat-card ${active.some(isOverdue) ? "danger" : "success"}"><span>Просрочено</span><strong>${active.filter(isOverdue).length}</strong><small>на текущую дату</small></div><div class="stat-card"><span>Встречи сегодня</span><strong>${meetings.length}</strong><small>${formatDate(today)}</small></div></section>
    <section class="dashboard-grid"><div class="panel dashboard-main"><div class="section-heading"><div><span class="eyebrow">Личное</span><h2>Ближайшие задачи</h2></div><a class="text-link" href="#tasks">Все задачи →</a></div>${active.slice(0, 5).map(taskMini).join("") || empty("Активных задач нет")}</div>
    <aside class="panel dashboard-side"><span class="eyebrow">Сегодня</span><h2>Встречи</h2>${meetings.map(m => `<div class="meeting-mini"><span>${esc(m.start)}–${esc(m.end)} · ${esc(m.type)}</span><strong>${esc(m.title)}</strong><small>${esc(m.room || "Онлайн")}</small></div>`).join("") || `<p class="muted">Встреч не запланировано.</p>`}<a class="button secondary full" href="#calendar">Открыть календарь</a></aside></section>`;
}
function isOverdue(task) { const deadline = safeDate(task.deadline); return task.workflow !== "Выполнено" && deadline && deadline < new Date(); }
function taskMini(task) { return `<a class="compact-task ${isOverdue(task) ? "task-overdue" : "task-active"}" href="#tasks/${task.id}"><span class="status-dot"></span><span class="compact-task-body"><strong>${esc(task.title)}</strong><small>${esc(task.department)} · ${esc(task.workflow)}</small></span><span class="compact-deadline">${formatDateTime(task.deadline)}<small>${esc(task.priority)}</small></span></a>`; }
function visibleTasks(completed) {
  const filter = state.taskFilter || { status: "", department: "", mine: false };
  const me = current();
  return state.tasks.filter(t => {
    const participant = [t.creator, ...t.assignees, ...t.observers, ...t.approvers].includes(state.currentEmployee);
    const canSee = me.role !== "employee" || participant;
    return canSee && (t.workflow === "Выполнено") === completed && (!filter.status || t.workflow === filter.status) && (!filter.department || t.department === filter.department) && (!filter.mine || participant);
  });
}
function tasks(completed) {
  const list = visibleTasks(completed);
  const departments = [...new Set(state.employees.filter(e => !e.archived).map(e => e.department))];
  const filter = state.taskFilter || {};
  app.innerHTML = header("Контроль исполнения", completed ? "Выполненные задачи" : "Задачи", "Локальная имитация маршрута согласования. Серверные права и файлы здесь не проверяются.", completed ? `<button class="button secondary" data-action="export-tasks">CSV</button>` : `<button class="button" data-action="new-task">+ Новая задача</button>`) + `
    <div class="tab-bar"><a class="${!completed ? "active" : ""}" href="#tasks">В работе</a><a class="${completed ? "active" : ""}" href="#completed">Выполненные</a></div>
    <section class="panel filter-bar"><label>Статус<select id="taskStatusFilter"><option value="">Все</option>${taskStages.map(s => `<option ${filter.status === s ? "selected" : ""}>${s}</option>`).join("")}</select></label><label>Отдел<select id="taskDepartmentFilter"><option value="">Все</option>${departments.map(d => `<option ${filter.department === d ? "selected" : ""}>${esc(d)}</option>`).join("")}</select></label><label class="check-field"><input id="taskMineFilter" type="checkbox" ${filter.mine ? "checked" : ""}> Только с моим участием</label><button class="button secondary" data-action="apply-task-filter">Применить</button><button class="button ghost" data-action="export-tasks">Экспорт CSV</button></section>
    <section class="panel table-panel">${list.length ? `<div class="table-wrap"><table><thead><tr><th>Задача</th><th>Участники</th><th>Дедлайн</th><th>Этап</th><th></th></tr></thead><tbody>${list.map(t => `<tr class="task-row ${isOverdue(t) ? "task-overdue" : ""}"><td><strong>${esc(t.title)}</strong><small>${esc(t.department)} · ${esc(t.description)}</small><span class="priority priority-${esc(t.priority.toLowerCase())}">${esc(t.priority)}</span></td><td>${t.assignees.map(id => `<span class="person-chip">${avatar(person(id), "avatar")}${esc(person(id)?.name || "Удалённый сотрудник")}</span>`).join("")}</td><td><strong>${formatDateTime(t.deadline)}</strong><small>${isOverdue(t) ? "Просрочено" : `Создано ${formatDate(t.createdAt)}`}</small></td><td><span class="status-badge status-active">${esc(t.workflow)}</span></td><td><a class="icon-action" href="#tasks/${t.id}">Открыть</a></td></tr>`).join("")}</tbody></table></div>` : empty(completed ? "Архив пуст" : "Задачи не найдены")}</section>`;
}
function taskDialog(id) {
  const task = state.tasks.find(t => t.id === Number(id)); if (!task) return toast("Задача не найдена");
  const me = current(); const assignee = task.assignees.includes(me.id); const approver = task.approvers.includes(me.id); const decision = task.decisions[me.id];
  if (me.role === "employee" && ![task.creator, ...task.assignees, ...task.observers, ...task.approvers].includes(me.id)) {
    history.replaceState(null, "", "#tasks");
    return toast("У выбранного профиля нет доступа к этой задаче");
  }
  const chips = values => values.map(value => `<span class="person-chip">${avatar(person(value), "avatar")}${esc(person(value)?.name || "Архив")}</span>`).join("");
  openModal(`<div class="modal-content task-dialog"><span class="eyebrow">Карточка задачи · ${esc(task.workflow)}</span><h2>${esc(task.title)}</h2><p>${esc(task.description)}</p>
    <div class="task-facts"><div><small>Отдел</small><strong>${esc(task.department)}</strong></div><div><small>Приоритет</small><strong>${esc(task.priority)}</strong></div><div><small>Дедлайн</small><strong>${formatDateTime(task.deadline)}</strong></div></div>
    <p><strong>Исполнители:</strong><br>${chips(task.assignees)}<br><strong>Наблюдатели:</strong><br>${chips(task.observers) || "Нет"}</p>
    <div class="approval-list">${task.approvers.map(id => `<div class="approval-card"><strong>${esc(person(id)?.name || "Архив")}</strong><small>${task.decisions[id] === "approved" ? "Согласовано" : task.decisions[id] === "revision" ? "Вернул на доработку" : "Ожидается решение"}</small></div>`).join("")}</div>
    <section class="history-list"><h3>Комментарии и история</h3>${[...task.history.map(h => ({ at: h.at, who: person(h.actor)?.name || "Система", text: h.text })), ...task.comments.map(c => ({ at: c.createdAt, who: person(c.author)?.name || "Архив", text: c.text }))].sort((a,b) => new Date(b.at)-new Date(a.at)).map(h => `<div class="history-entry"><strong>${esc(h.who)}</strong><span>${esc(h.text)}</span><small>${formatDateTime(h.at)}</small></div>`).join("")}</section>
    <form id="taskCommentForm" data-id="${task.id}" class="inline-form"><input name="text" required maxlength="500" placeholder="Комментарий от ${esc(me.name)}"><button class="button secondary">Добавить</button></form>
    ${assignee && ["Новая", "В работе", "На доработке"].includes(task.workflow) ? `<button class="button" data-action="advance-task" data-id="${task.id}">${task.workflow === "Новая" ? "Начать работу" : "Отправить на проверку"}</button>` : ""}
    ${approver && task.workflow === "На проверке" && !decision ? `<div class="approval-actions"><button class="button" data-action="approve-task" data-id="${task.id}">Согласовать от моего профиля</button><button class="button danger" data-action="revision-task" data-id="${task.id}">Вернуть на доработку</button></div>` : ""}
    ${decision ? `<p class="muted">Решение текущего согласующего уже сохранено.</p>` : ""}
    ${(approver || me.role !== "employee") ? `<details class="advanced-settings"><summary>Заменить участника вручную</summary><form id="replacementForm" data-id="${task.id}" class="advanced-grid"><label class="field"><span>Роль</span><select name="role"><option value="assignees">Исполнитель</option><option value="observers">Наблюдатель</option><option value="approvers">Согласующий</option></select></label><label class="field"><span>Кого заменить</span><select name="from">${task.assignees.map(id => `<option value="${id}">Исполнитель · ${esc(person(id)?.name)}</option>`).join("")}${task.observers.map(id => `<option value="${id}">Наблюдатель · ${esc(person(id)?.name)}</option>`).join("")}${task.approvers.map(id => `<option value="${id}">Согласующий · ${esc(person(id)?.name)}</option>`).join("")}</select></label><label class="field"><span>Кем заменить</span><select name="to">${employeeOptions()}</select></label><label class="field"><span>Причина *</span><input name="reason" required maxlength="200"></label><button class="button secondary">Сохранить замену</button></form></details>` : ""}
  </div>`);
}
function taskForm(prefill = "") {
  const departments = [...new Set(state.employees.filter(e => !e.archived).map(e => e.department))];
  openModal(`<form class="modal-content" id="taskForm"><span class="eyebrow">Новая задача</span><h2>Создать задачу</h2><div class="form-grid">
    <label class="field field-wide"><span>Название *</span><input name="title" value="${esc(prefill)}" required maxlength="120"></label><label class="field field-wide"><span>Описание *</span><textarea name="description" required maxlength="1000"></textarea></label>
    <label class="field"><span>Отдел *</span><select name="department" required>${departments.map(d => `<option>${esc(d)}</option>`).join("")}</select></label><label class="field"><span>Приоритет</span><select name="priority"><option>Обычная</option><option>Важная</option><option>Срочная</option><option>Критическая</option></select></label>
    <label class="field"><span>Исполнители * (можно несколько)</span><select name="assignees" multiple required>${employeeOptions()}</select></label><label class="field"><span>Наблюдатели</span><select name="observers" multiple>${employeeOptions()}</select></label>
    <label class="field"><span>Согласующий 1 *</span><select name="approver1" required>${employeeOptions()}</select></label><label class="field"><span>Согласующий 2 * (другой)</span><select name="approver2" required>${employeeOptions()}</select></label>
    <label class="field field-wide"><span>Дедлайн *</span><input type="datetime-local" name="deadline" value="${addDays(3, "17:00")}" required></label></div><p class="form-error" id="taskFormError"></p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Отмена</button><button class="button">Создать</button></div></form>`);
}

function startOfWeek() { const date = new Date(); date.setHours(12,0,0,0); const day = date.getDay() || 7; date.setDate(date.getDate() - day + 1); return date; }
function calendar() {
  const monday = startOfWeek(); const week = Array.from({length: 7}, (_, i) => { const d = new Date(monday); d.setDate(d.getDate() + i); return d; });
  const days = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];
  const upcoming = [...state.meetings].sort((a,b) => `${a.date}T${a.start}`.localeCompare(`${b.date}T${b.start}`));
  app.innerHTML = header("Единый центр событий", "Календарь", "Текущая неделя, встречи и бронирование помещений с проверкой пересечений.", `<button class="button" data-action="new-meeting">+ Встреча / бронь</button>`) + `
    <section class="panel calendar-events"><div class="section-heading"><div><span class="eyebrow">Неделя</span><h2>${formatDate(week[0])} — ${formatDate(week[6])}</h2></div></div><div class="week-events">${week.map((d,i) => { const key=localDate(d); const events=state.meetings.filter(m=>m.date===key&&m.status!=="Отменена"); const birthdays=state.employees.filter(e=>!e.archived&&e.birthDate?.slice(5)===key.slice(5)); return `<div class="${key===localDate()?"today":""}"><strong>${days[i]} · ${formatDate(key,{day:"2-digit",month:"2-digit"})}</strong>${events.map(m=>`<button class="calendar-event" data-action="meeting" data-id="${m.id}">${esc(m.start)} ${esc(m.title)}</button>`).join("")}${birthdays.map(e=>`<small>День рождения: ${esc(e.name)}</small>`).join("")}${!events.length&&!birthdays.length?`<small>Нет событий</small>`:""}</div>`; }).join("")}</div></section>
    <section class="calendar-meetings"><div class="section-heading"><div><span class="eyebrow">Ближайшие и прошедшие</span><h2>Созданные встречи и брони</h2></div></div><div class="meeting-grid">${upcoming.map(m=>`<article class="meeting-card ${safeDate(`${m.date}T${m.end}`)<new Date()?"past":""}"><div class="meeting-date"><strong>${esc(m.date.slice(8))}</strong><span>${formatDate(m.date,{month:"short"})}</span></div><div class="meeting-content"><span>${esc(m.type)} · ${esc(m.start)}–${esc(m.end)}</span><h2>${esc(m.title)}</h2><p>${esc(m.room||"Без помещения")} · ${m.participants.length} участника(ов)</p><small>${esc(m.notes||"Без заметок")} ${m.status==="Отменена"?" · ОТМЕНЕНА":""}</small></div><button class="button secondary" data-action="meeting" data-id="${m.id}">Подробнее</button></article>`).join("") || empty("Встреч пока нет")}</div></section>`;
}
function meetingForm() {
  openModal(`<form class="modal-content" id="meetingForm"><span class="eyebrow">Календарь</span><h2>Новая встреча или бронь</h2><div class="form-grid"><label class="field field-wide"><span>Тема *</span><input name="title" required maxlength="120"></label><label class="field"><span>Дата *</span><input type="date" name="date" min="${localDate()}" value="${localDate()}" required></label><label class="field"><span>Тип</span><select name="type"><option>Очная</option><option>Онлайн</option><option>Гибридная</option></select></label><label class="field"><span>Начало *</span><input type="time" name="start" value="10:00" required></label><label class="field"><span>Окончание *</span><input type="time" name="end" value="11:00" required></label><label class="field"><span>Помещение</span><select name="room"><option value="">Не требуется</option><option>Актовый зал</option><option>Конференц-зал</option><option>Переговорная 305</option></select></label><label class="field"><span>Участники *</span><select name="participants" multiple required>${employeeOptions([state.currentEmployee])}</select></label><label class="field field-wide"><span>Ссылка HTTP(S)</span><input type="url" name="link" placeholder="https://..."></label><label class="field field-wide"><span>Заметки</span><textarea name="notes" maxlength="1000"></textarea></label></div><p class="form-error" id="meetingFormError"></p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Отмена</button><button class="button">Создать</button></div></form>`);
}
function meetingDialog(id) { const m=state.meetings.find(x=>x.id===id); if(!m)return; openModal(`<div class="modal-content"><span class="eyebrow">${esc(m.status)}</span><h2>${esc(m.title)}</h2><p><strong>${formatDate(m.date)}, ${esc(m.start)}–${esc(m.end)}</strong><br>${esc(m.type)} · ${esc(m.room||"без помещения")}</p><p>${esc(m.notes||"Заметок нет")}</p><p><strong>Участники:</strong><br>${m.participants.map(id=>esc(person(id)?.name||"Архив")).join(", ")}</p>${m.link?`<a class="button secondary" href="${esc(m.link)}" target="_blank" rel="noreferrer">Открыть ссылку</a>`:""}${m.status!=="Отменена"&&m.organizer===state.currentEmployee?`<button class="button danger" data-action="cancel-meeting" data-id="${m.id}">Отменить встречу</button>`:""}</div>`); }

function accessibleChats() { return state.chats.filter(c => c.members.includes(state.currentEmployee)); }
function messages() {
  const available=accessibleChats(); let chat=available.find(c=>c.id===state.activeChat)||available[0]; if(chat)state.activeChat=chat.id;
  app.innerHTML=header("На связи","Сообщения","Приватные и групповые комнаты видны только их участникам в рамках демо-профиля.",`<button class="button" data-action="new-chat">+ Новая беседа</button>`)+demoNotice()+`<div class="chat-layout"><aside class="panel chat-sidebar"><h2>Беседы</h2>${available.map(c=>`<button class="chat-room ${c.id===chat?.id?"active":""}" data-action="chat" data-id="${c.id}"><strong>${c.kind==="private"?"Личная":"Группа"}</strong><br>${esc(c.name)}</button>`).join("")||`<p>Нет доступных бесед.</p>`}</aside><section class="panel chat-conversation">${chat?`<div class="chat-heading"><div><h2>${esc(chat.name)}</h2><small>${chat.members.map(id=>esc(person(id)?.name||"Архив")).join(", ")}</small></div>${chat.callLink?`<a class="button secondary" href="${esc(chat.callLink)}" target="_blank" rel="noreferrer">Позвонить</a>`:`<span class="no-link">Ссылка не сохранена</span>`}</div><div class="chat-thread">${chat.messages.map(m=>`<article class="chat-message ${m.author===state.currentEmployee?"mine":""}"><span class="person-chip">${avatar(person(m.author),"avatar")}${esc(person(m.author)?.name||"Архив")}</span><small>${formatDateTime(m.createdAt)}</small><p>${esc(m.text)}</p>${m.attachment?`<span class="attachment-demo">Файл (только метаданные демо): ${esc(m.attachment)}</span>`:""}<button class="message-task-link" data-action="message-task" data-text="${esc(m.text)}">Создать задачу из сообщения</button></article>`).join("")||empty("Сообщений пока нет")}</div><form class="chat-send" id="messageForm" data-id="${chat.id}"><textarea name="text" rows="2" placeholder="Напишите сообщение..."></textarea><label class="field"><span>Вложение (имя файла, демо)</span><input name="attachment" type="file"></label><button class="button">Отправить</button></form><form class="chat-call-form" id="callLinkForm" data-id="${chat.id}"><label>Ссылка для звонка HTTP(S)</label><div><input name="link" type="url" value="${esc(chat.callLink)}" placeholder="https://..."><button class="button secondary">Сохранить</button></div></form>`:empty("Выберите или создайте беседу")}</section></div>`;
}
function chatForm(){openModal(`<form class="modal-content" id="chatForm"><span class="eyebrow">Сообщения</span><h2>Новая беседа</h2><label class="field"><span>Название *</span><input name="name" required maxlength="80"></label><label class="field"><span>Тип</span><select name="kind"><option value="private">Личная</option><option value="group">Групповая</option></select></label><label class="field"><span>Участники *</span><select name="members" multiple required>${employeeOptions([], [state.currentEmployee])}</select></label><p class="muted">Текущий профиль будет добавлен автоматически. Для личной беседы выберите ровно одного коллегу.</p><p class="form-error" id="chatFormError"></p><div class="form-actions"><button class="button">Создать</button></div></form>`)}

function employees(){const active=state.employees.filter(e=>!e.archived),archived=state.employees.filter(e=>e.archived);const departments=[...new Set(active.map(e=>e.department))],canManage=current().role!=="employee";app.innerHTML=header("Команда","Сотрудники ПИОНЕР","Карточки содержат демонстрационные сведения и используют только сгенерированные инициалы.",canManage?`<button class="button" data-action="new-employee">+ Добавить сотрудника</button>`:"")+`<div class="employee-toolbar"><div class="employee-filters"><input id="employeeSearch" type="search" placeholder="Поиск по имени или должности"><select id="departmentFilter"><option value="">Все отделы</option>${departments.map(d=>`<option>${esc(d)}</option>`).join("")}</select></div></div><div class="employee-grid" id="employeeGrid">${active.map(employeeCard).join("")}</div>${archived.length?`<details class="panel archive-panel"><summary>Архив сотрудников · ${archived.length}</summary><div class="employee-grid">${archived.map(employeeCard).join("")}</div></details>`:""}`;}
function employeeCard(e){return `<button class="employee-card" data-action="employee" data-id="${e.id}" data-search="${esc((e.name+" "+e.position).toLowerCase())}" data-department="${esc(e.department)}">${avatar(e,"employee-photo placeholder")}<span class="employee-details"><span>${esc(e.department)}</span><h2>${esc(e.name)}</h2><span class="presence-label">${esc(e.status)}</span><p>${esc(e.position)}</p><small>${esc(e.email||"Email не указан")}</small></span></button>`;}
function employeeDialog(id){const e=person(id);if(!e)return;const head=person(e.departmentHead),sub=person(e.substitute),canManage=current().role!=="employee";openModal(`<div class="modal-content"><div class="profile-overview">${avatar(e,"profile-photo profile-placeholder")}<div class="profile-summary"><span class="eyebrow">${e.archived?"Архив":"Карточка сотрудника"}</span><h2>${esc(e.name)}</h2><p>${esc(e.position)} · ${esc(e.department)}</p></div></div><dl class="profile-facts"><div><dt>Email</dt><dd>${esc(e.email||"Не указан")}</dd></div><div><dt>Возраст</dt><dd>${age(e.birthDate)}</dd></div><div><dt>Статус</dt><dd>${esc(e.status)}</dd></div><div><dt>Руководитель</dt><dd>${esc(head?.name||"Не указан")}</dd></div><div><dt>Личный заместитель</dt><dd>${esc(sub?.name||"Не указан")}</dd></div><div><dt>Свободные окна</dt><dd>${esc(e.freeSlots||"Не указаны")}</dd></div></dl>${e.absenceFrom||e.absenceTo?`<p><strong>Период отсутствия:</strong> ${formatDate(e.absenceFrom)} — ${formatDate(e.absenceTo)}</p>`:""}${!e.archived&&canManage?`<div class="form-actions"><button class="button secondary" data-action="edit-employee" data-id="${e.id}">Редактировать</button><button class="button danger" data-action="dismiss-employee" data-id="${e.id}">В архив / уволить</button></div>`:""}</div>`)}
function employeeForm(editId){const e=editId?person(editId):null;openModal(`<form class="modal-content" id="employeeForm" data-id="${e?.id||""}"><span class="eyebrow">${e?"Редактирование":"Новый сотрудник"}</span><h2>${e?esc(e.name):"Добавить сотрудника"}</h2><div class="form-grid"><label class="field field-wide"><span>ФИО *</span><input name="name" value="${esc(e?.name)}" required minlength="3" maxlength="100"></label><label class="field"><span>Отдел *</span><input name="department" value="${esc(e?.department)}" required></label><label class="field"><span>Должность *</span><input name="position" value="${esc(e?.position)}" required></label><label class="field"><span>Email *</span><input type="email" name="email" value="${esc(e?.email)}" required></label><label class="field"><span>Дата рождения</span><input type="date" name="birthDate" value="${esc(e?.birthDate)}" max="${localDate()}"></label><label class="field"><span>Роль (имитация)</span><select name="role">${[["employee","Сотрудник"],["manager","Руководитель"],["admin","Администратор"]].map(([v,l])=>`<option value="${v}" ${e?.role===v?"selected":""}>${l}</option>`).join("")}</select></label><label class="field"><span>Статус</span><select name="status">${statuses.map(s=>`<option ${e?.status===s?"selected":""}>${s}</option>`).join("")}</select></label><label class="field"><span>Руководитель отдела</span><select name="departmentHead"><option value="">Не указан</option>${employeeOptions(e?.departmentHead?[e.departmentHead]:[])}</select></label><label class="field"><span>Личный заместитель</span><select name="substitute"><option value="">Не указан</option>${employeeOptions(e?.substitute?[e.substitute]:[],e?[e.id]:[])}</select></label><label class="field field-wide"><span>Свободные окна</span><input name="freeSlots" value="${esc(e?.freeSlots)}"></label><label class="field"><span>Отсутствует с</span><input type="date" name="absenceFrom" value="${esc(e?.absenceFrom)}"></label><label class="field"><span>Отсутствует по</span><input type="date" name="absenceTo" value="${esc(e?.absenceTo)}"></label></div><p class="form-error" id="employeeFormError"></p><div class="form-actions"><button class="button">Сохранить</button></div></form>`)}

function feed(){const me=current();const filter=state.feedFilter||"all",canPublish=me.role!=="employee";const posts=state.posts.filter(p=>(p.audience==="all"||p.audience===me.department||p.author===me.id)&&(filter==="all"||filter==="mine"&&p.author===me.id||filter==="important"&&p.type.includes("Важное")));app.innerHTML=header("Жизнь компании","Лента ПИОНЕР","Аудитории, четыре реакции от каждого демо-профиля и обсуждения.",canPublish?`<button class="button" data-action="new-post">+ Публикация</button>`:"")+`<div class="tab-bar"><button class="${filter==="all"?"active":""}" data-action="feed-filter" data-filter="all">Все доступные</button><button class="${filter==="important"?"active":""}" data-action="feed-filter" data-filter="important">Важные</button><button class="${filter==="mine"?"active":""}" data-action="feed-filter" data-filter="mine">Мои</button></div><div class="feed-layout"><section class="feed-list">${posts.map(postCard).join("")||empty("Нет публикаций для этого профиля")}</section><aside class="feed-note"><strong>Видимость аудитории</strong><p>Профиль видит общие публикации, новости своего отдела и собственные записи. Это только интерфейсная симуляция.</p></aside></div>`;}
function postCard(p){const author=person(p.author);return `<article class="post-card ${p.type.includes("Важное")?"important":""}"><header class="post-header">${avatar(author,"avatar")}<div><strong>${esc(author?.name||"Архив")}</strong><small>${formatDateTime(p.createdAt)} · ${p.audience==="all"?"Для всех":`Отдел: ${esc(p.audience)}`}</small></div><span class="post-type">${esc(p.type)}</span></header><div class="post-text">${esc(p.text)}</div><div class="reaction-row">${reactions.map(([key,label])=>{const list=p.reactions[key]||[];return `<button class="reaction-button ${list.includes(state.currentEmployee)?"active":""}" data-action="react" data-id="${p.id}" data-reaction="${key}">${label} · ${list.length}</button>`}).join("")}</div>${p.author===state.currentEmployee?`<div class="owner-actions"><button data-action="edit-post" data-id="${p.id}">Редактировать</button><button data-action="delete-post" data-id="${p.id}">Удалить</button></div>`:""}<div class="comments">${p.comments.map(c=>`<div class="comment"><strong>${esc(person(c.author)?.name||"Архив")}</strong><span>${esc(c.text)}</span><small>${formatDateTime(c.createdAt)}</small></div>`).join("")}</div><form class="comment-form" data-post-id="${p.id}"><input name="text" required maxlength="500" placeholder="Комментарий от ${esc(current().name)}"><button>Отправить</button></form></article>`;}
function postForm(post){const departments=[...new Set(state.employees.filter(e=>!e.archived).map(e=>e.department))];openModal(`<form class="modal-content" id="postForm" data-id="${post?.id||""}"><span class="eyebrow">Лента</span><h2>${post?"Редактировать":"Новая публикация"}</h2><label class="field"><span>Тип</span><select name="type"><option ${post?.type==="Новость"?"selected":""}>Новость</option><option ${post?.type==="Важное объявление"?"selected":""}>Важное объявление</option></select></label><label class="field"><span>Аудитория</span><select name="audience"><option value="all">Все сотрудники</option>${departments.map(d=>`<option ${post?.audience===d?"selected":""}>${esc(d)}</option>`).join("")}</select></label><label class="field"><span>Текст *</span><textarea name="text" rows="6" required maxlength="2000">${esc(post?.text)}</textarea></label><div class="form-actions"><button class="button">Сохранить</button></div></form>`)}

function analyticsData(){const f=state.analyticsFilter||{period:"all",department:""};const cutoff=new Date();if(f.period==="week")cutoff.setDate(cutoff.getDate()-7);if(f.period==="month")cutoff.setMonth(cutoff.getMonth()-1);return state.tasks.filter(t=>(f.period==="all"||safeDate(t.createdAt)>=cutoff)&&(!f.department||t.department===f.department));}
function analytics(){const departments=[...new Set(state.employees.filter(e=>!e.archived).map(e=>e.department))],f=state.analyticsFilter||{},list=analyticsData();const breakdown=departments.filter(d=>!f.department||d===f.department).map(d=>({name:d,newCount:list.filter(t=>t.department===d&&t.workflow==="Новая").length,work:list.filter(t=>t.department===d&&["В работе","На доработке"].includes(t.workflow)).length,review:list.filter(t=>t.department===d&&t.workflow==="На проверке").length,done:list.filter(t=>t.department===d&&t.workflow==="Выполнено").length}));const ranking=state.employees.filter(e=>!e.archived).map(e=>({name:e.name,department:e.department,done:list.filter(t=>t.workflow==="Выполнено"&&t.assignees.includes(e.id)).length,active:list.filter(t=>t.workflow!=="Выполнено"&&t.assignees.includes(e.id)).length})).filter(x=>!f.department||x.department===f.department).sort((a,b)=>b.done-a.done||a.active-b.active);app.innerHTML=header("Показатели","Аналитика","Расчёт строится только по локальным задачам демоверсии.",`<button class="button secondary" data-action="export-analytics">Точный CSV отчёта</button>`)+`<section class="panel filter-bar"><label>Период<select id="analyticsPeriod"><option value="all">Всё время</option><option value="week" ${f.period==="week"?"selected":""}>7 дней</option><option value="month" ${f.period==="month"?"selected":""}>30 дней</option></select></label><label>Отдел<select id="analyticsDepartment"><option value="">Все отделы</option>${departments.map(d=>`<option ${f.department===d?"selected":""}>${esc(d)}</option>`).join("")}</select></label><button class="button secondary" data-action="apply-analytics">Применить</button></section><section class="stats-grid"><div class="stat-card"><span>Всего задач</span><strong>${list.length}</strong></div><div class="stat-card success"><span>Выполнено</span><strong>${list.filter(t=>t.workflow==="Выполнено").length}</strong></div><div class="stat-card danger"><span>Просрочено</span><strong>${list.filter(isOverdue).length}</strong></div></section><section class="analytics-grid"><div class="panel analytics-ranking"><div class="section-heading"><h2>Статусы по отделам</h2></div><div class="table-wrap"><table><thead><tr><th>Отдел</th><th>Новые</th><th>В работе / доработка</th><th>Проверка</th><th>Выполнено</th></tr></thead><tbody>${breakdown.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.newCount}</td><td>${x.work}</td><td>${x.review}</td><td>${x.done}</td></tr>`).join("")}</tbody></table></div></div><div class="panel analytics-ranking"><div class="section-heading"><h2>Рейтинг сотрудников</h2></div>${ranking.map((x,i)=>`<div class="ranking-row"><strong>${i+1}. ${esc(x.name)}</strong><span>${x.done} выполнено · ${x.active} активно</span></div>`).join("")}</div></section>`;}

function settings(){const admin=current().role==="admin";app.innerHTML=header("Управление","Настройки","Параметры сохраняются только в localStorage этого браузера.")+demoNotice()+`<div class="settings-grid"><section class="panel settings-panel"><span class="eyebrow">Оформление</span><h2>Тема и цвет</h2><form id="settingsForm"><label class="field"><span>Тема</span><select name="theme"><option value="light">Светлая</option><option value="dark" ${state.settings.theme==="dark"?"selected":""}>Тёмная</option></select></label><label class="field"><span>Основной цвет</span><input type="color" name="color" value="${esc(state.settings.color)}"></label><label class="check-field"><input type="checkbox" name="sound" ${state.settings.sound?"checked":""}> Звук уведомлений</label><div class="form-actions"><button class="button">Применить</button></div></form></section><section class="panel settings-panel"><span class="eyebrow">Данные</span><h2>Демонстрационное состояние</h2><p>Сброс удалит все изменения этого демо только из текущего браузера.</p><button class="button danger" data-action="reset" ${admin?"":"disabled"}>Сбросить демо-данные</button><small>${admin?"Доступно роли администратора.":"Скрыто сервером не будет: кнопка отключена только интерфейсом демо."}</small></section></div>`;}

function notifications(){const list=state.notifications.filter(n=>n.recipient===state.currentEmployee);openModal(`<div class="modal-content"><div class="section-heading"><div><span class="eyebrow">${esc(current().name)}</span><h2>Уведомления</h2></div><button class="text-link" data-action="read-all">Прочитать все</button></div><div class="notification-list">${list.map(n=>`<a class="notification-item ${n.read?"":"unread"}" href="${esc(n.link||"#overview")}" data-action="open-notification" data-id="${n.id}"><span class="notification-icon">i</span><span><strong>${esc(n.text)}</strong><small>${formatDateTime(n.createdAt)}</small></span>${n.read?"":"<i></i>"}</a>`).join("")||empty("Уведомлений нет")}</div></div>`)}
function profile(){openModal(`<div class="modal-content"><span class="eyebrow">Симуляция профиля и прав</span><h2>Кем открыть демо?</h2><p>Переключение не является входом и не защищает данные.</p><div class="profile-list">${state.employees.filter(e=>!e.archived).map(e=>`<button class="profile-choice chat-room ${e.id===state.currentEmployee?"active":""}" data-action="select-employee" data-id="${e.id}">${avatar(e,"avatar")}<span><strong>${esc(e.name)}</strong><small>${esc(e.position)} · ${esc(e.role)}</small></span></button>`).join("")}</div></div>`)}
function openModal(html){modalBody.innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){if(modal.open)modal.close();modalBody.innerHTML="";if(route().name==="tasks"&&route().id)history.replaceState(null,"", "#tasks");}
function validHttp(value){if(!value)return true;try{return ["http:","https:"].includes(new URL(value).protocol)}catch{return false}}
function downloadCsv(name,rows){const csv="\ufeff"+rows.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(";")).join("\r\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0)}
function exportTasks(){const list=route().name==="completed"?visibleTasks(true):visibleTasks(false);downloadCsv("pioneer-tasks-demo.csv",[["ID","Задача","Описание","Отдел","Исполнители","Наблюдатели","Согласующий 1","Согласующий 2","Приоритет","Создано","Дедлайн","Статус"],...list.map(t=>[t.id,t.title,t.description,t.department,t.assignees.map(id=>person(id)?.name).join(", "),t.observers.map(id=>person(id)?.name).join(", "),person(t.approvers[0])?.name,person(t.approvers[1])?.name,t.priority,t.createdAt,t.deadline,t.workflow])])}
function exportAnalytics(){const list=analyticsData();downloadCsv("pioneer-analytics-demo.csv",[["ID","Задача","Отдел","Статус","Просрочено","Исполнители","Создано","Дедлайн"],...list.map(t=>[t.id,t.title,t.department,t.workflow,isOverdue(t)?"Да":"Нет",t.assignees.map(id=>person(id)?.name).join(", "),t.createdAt,t.deadline])])}
function autoSubstitute(employee){if(!absentStatuses.has(employee.status)||!employee.substitute)return 0;let count=0;state.tasks.filter(t=>t.workflow!=="Выполнено").forEach(t=>{for(const role of ["assignees","observers","approvers"]){if(!t[role].includes(employee.id)||t[role].includes(employee.substitute))continue;t[role]=t[role].map(id=>id===employee.id?employee.substitute:id);t.substitutions??=[];t.substitutions.push({role,original:employee.id,replacement:employee.substitute,active:true,at:nowIso()});if(role==="approvers")t.decisions={};t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Автозамена (${roleLabel(role)}): ${employee.name} → ${person(employee.substitute)?.name}. Причина: ${employee.status}`});addNotification(employee.substitute,`Вы автоматически назначены в задачу «${t.title}» на период отсутствия коллеги`,`#tasks/${t.id}`);count++}});return count;}
function restoreSubstitutions(employee){let count=0;state.tasks.filter(t=>t.workflow!=="Выполнено").forEach(t=>(t.substitutions||[]).filter(s=>s.active&&s.original===employee.id).forEach(s=>{t[s.role]=t[s.role].map(id=>id===s.replacement?employee.id:id);s.active=false;t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Возврат участника (${roleLabel(s.role)}): ${person(s.replacement)?.name} → ${employee.name}`});count++}));return count;}
function roleLabel(role){return {assignees:"исполнитель",observers:"наблюдатель",approvers:"согласующий"}[role]||role;}

document.addEventListener("submit",event=>{
  const form=event.target;if(!form.matches("form"))return;event.preventDefault();const data=new FormData(form);
  if(form.id==="taskForm"){const approvers=[Number(data.get("approver1")),Number(data.get("approver2"))],assignees=selected(form,"assignees");if(approvers[0]===approvers[1])return $("#taskFormError").textContent="Нужны ровно два разных согласующих.";if(!assignees.length)return $("#taskFormError").textContent="Выберите хотя бы одного исполнителя.";const id=Date.now();const task={id,title:data.get("title").trim(),description:data.get("description").trim(),department:data.get("department"),assignees,observers:selected(form,"observers"),approvers,creator:state.currentEmployee,priority:data.get("priority"),createdAt:nowIso(),deadline:data.get("deadline"),workflow:"Новая",decisions:{},comments:[],history:[{at:nowIso(),actor:state.currentEmployee,text:"Задача создана"}]};state.tasks.unshift(task);new Set([...assignees,...task.observers,...approvers]).forEach(user=>addNotification(user,`Вы участник новой задачи «${task.title}»`,`#tasks/${id}`));save();closeModal();location.hash=`tasks/${id}`;render();toast("Задача создана");}
  if(form.id==="taskCommentForm"){const task=state.tasks.find(t=>t.id===Number(form.dataset.id));task.comments.push({id:Date.now(),author:state.currentEmployee,text:data.get("text").trim(),createdAt:nowIso()});save();taskDialog(task.id);}
  if(form.id==="replacementForm"){const task=state.tasks.find(t=>t.id===Number(form.dataset.id)),role=data.get("role"),from=Number(data.get("from")),to=Number(data.get("to"));if(current().role==="employee"&&!task.approvers.includes(state.currentEmployee))return toast("У выбранного профиля нет права менять участников");if(!["assignees","observers","approvers"].includes(role)||!task[role].includes(from))return toast("Выберите участника указанной роли");if(!to||from===to||task[role].includes(to))return toast("Выберите другого сотрудника, которого ещё нет в этой роли");task[role]=task[role].map(id=>id===from?to:id);if(role==="approvers")task.decisions={};task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Ручная замена (${roleLabel(role)}): ${person(from)?.name} → ${person(to)?.name}. Причина: ${data.get("reason")}`});addNotification(to,`Вы назначены в задачу «${task.title}» после ручной замены`,`#tasks/${task.id}`);addNotification(from,`Ваша роль в задаче «${task.title}» передана другому сотруднику`,`#tasks/${task.id}`);save();taskDialog(task.id);toast("Замена сохранена в истории");}
  if(form.id==="meetingForm"){const start=data.get("start"),end=data.get("end"),room=data.get("room"),date=data.get("date"),link=data.get("link").trim();if(start>=end)return $("#meetingFormError").textContent="Окончание должно быть позже начала.";if(!validHttp(link))return $("#meetingFormError").textContent="Разрешены только ссылки HTTP(S).";const overlap=room&&state.meetings.some(m=>m.status!=="Отменена"&&m.room===room&&m.date===date&&start<m.end&&end>m.start);if(overlap)return $("#meetingFormError").textContent=`${room} уже занят в выбранный интервал.`;const participants=selected(form,"participants");if(!participants.length)return $("#meetingFormError").textContent="Выберите участников.";const meeting={id:Date.now(),title:data.get("title").trim(),date,start,end,type:data.get("type"),room,participants,organizer:state.currentEmployee,link,notes:data.get("notes").trim(),status:"Запланирована",createdAt:nowIso()};state.meetings.push(meeting);participants.forEach(id=>id!==state.currentEmployee&&addNotification(id,`Встреча «${meeting.title}» назначена на ${formatDate(date)} ${start}`,"#calendar"));save();closeModal();render();toast("Встреча и бронь добавлены");}
  if(form.id==="messageForm"){const chat=state.chats.find(c=>c.id===Number(form.dataset.id)),file=form.elements.attachment.files[0],text=data.get("text").trim();if(!text&&!file)return toast("Введите сообщение или выберите файл");chat.messages.push({id:Date.now(),author:state.currentEmployee,text,createdAt:nowIso(),attachment:file?.name||""});chat.members.filter(id=>id!==state.currentEmployee).forEach(id=>addNotification(id,`Новое сообщение в «${chat.name}»`,"#messages"));save();messages();}
  if(form.id==="callLinkForm"){const chat=state.chats.find(c=>c.id===Number(form.dataset.id)),link=data.get("link").trim();if(!validHttp(link))return toast("Нужна корректная ссылка HTTP(S)");chat.callLink=link;save();messages();toast("Ссылка сохранена");}
  if(form.id==="chatForm"){const members=selected(form,"members"),kind=data.get("kind");if(kind==="private"&&members.length!==1)return $("#chatFormError").textContent="Для личной беседы выберите одного коллегу.";if(!members.length)return $("#chatFormError").textContent="Выберите участников.";const chat={id:Date.now(),name:data.get("name").trim(),kind,members:[state.currentEmployee,...members],callLink:"",messages:[]};state.chats.push(chat);state.activeChat=chat.id;save();closeModal();messages();}
  if(form.id==="employeeForm"){const editId=Number(form.dataset.id),email=data.get("email").trim().toLowerCase();if(current().role==="employee")return toast("У выбранного профиля нет права управления сотрудниками");if(state.employees.some(e=>e.email?.toLowerCase()===email&&e.id!==editId))return $("#employeeFormError").textContent="Этот email уже используется.";if(data.get("absenceFrom")&&data.get("absenceTo")&&data.get("absenceFrom")>data.get("absenceTo"))return $("#employeeFormError").textContent="Проверьте период отсутствия.";const values={name:data.get("name").trim(),department:data.get("department").trim(),position:data.get("position").trim(),email,birthDate:data.get("birthDate"),role:data.get("role"),status:data.get("status"),departmentHead:Number(data.get("departmentHead"))||null,substitute:Number(data.get("substitute"))||null,freeSlots:data.get("freeSlots").trim(),absenceFrom:data.get("absenceFrom"),absenceTo:data.get("absenceTo")};let target,returned=0;if(editId){target=person(editId);const wasAbsent=absentStatuses.has(target.status);Object.assign(target,values);if(wasAbsent&&!absentStatuses.has(target.status))returned=restoreSubstitutions(target)}else{target={id:Date.now(),...values,archived:false};state.employees.push(target)}const replacements=autoSubstitute(target);save();closeModal();employees();toast(replacements?`Сотрудник сохранён. Автозамен: ${replacements}`:returned?`Сотрудник вернулся. Восстановлено ролей: ${returned}`:"Сотрудник сохранён");}
  if(form.id==="postForm"){if(current().role==="employee")return toast("У выбранного профиля нет права публиковать новости");const id=Number(form.dataset.id),post=state.posts.find(p=>p.id===id);if(post&&post.author!==state.currentEmployee)return toast("Редактировать публикацию может только её автор");if(post){post.type=data.get("type");post.audience=data.get("audience");post.text=data.get("text").trim();post.editedAt=nowIso()}else state.posts.unshift({id:Date.now(),author:state.currentEmployee,type:data.get("type"),audience:data.get("audience"),text:data.get("text").trim(),createdAt:nowIso(),reactions:{like:[],useful:[],support:[],celebrate:[]},comments:[]});save();closeModal();feed();toast("Публикация сохранена");}
  if(form.matches("[data-post-id]")){const post=state.posts.find(p=>p.id===Number(form.dataset.postId));post.comments.push({id:Date.now(),author:state.currentEmployee,text:data.get("text").trim(),createdAt:nowIso()});save();feed();}
  if(form.id==="settingsForm"){state.settings={color:data.get("color"),theme:data.get("theme"),sound:data.get("sound")==="on"};save();render();toast("Настройки применены");}
});

document.addEventListener("click",event=>{const target=event.target.closest("[data-action]");if(!target)return;const action=target.dataset.action,id=Number(target.dataset.id);
  if(action==="close-modal")closeModal();
  if(action==="notifications")notifications(); if(action==="profile")profile(); if(action==="new-task")taskForm(); if(action==="new-meeting")meetingForm(); if(action==="meeting")meetingDialog(id); if(action==="new-chat")chatForm(); if(action==="new-employee"&&current().role!=="employee")employeeForm(); if(action==="employee")employeeDialog(id); if(action==="edit-employee"&&current().role!=="employee")employeeForm(id); if(action==="new-post"&&current().role!=="employee")postForm();
  if(action==="apply-task-filter"){state.taskFilter={status:$("#taskStatusFilter").value,department:$("#taskDepartmentFilter").value,mine:$("#taskMineFilter").checked};save();render()}
  if(action==="export-tasks")exportTasks(); if(action==="export-analytics")exportAnalytics();
  if(action==="apply-analytics"){state.analyticsFilter={period:$("#analyticsPeriod").value,department:$("#analyticsDepartment").value};save();analytics()}
  if(action==="advance-task"){const t=state.tasks.find(x=>x.id===id);if(!t.assignees.includes(state.currentEmployee))return toast("Только назначенный исполнитель может менять этот этап");t.workflow=t.workflow==="Новая"?"В работе":"На проверке";if(t.workflow==="На проверке")t.decisions={};t.history.push({at:nowIso(),actor:state.currentEmployee,text:t.workflow==="В работе"?"Работа начата":"Отправлено на проверку"});t.approvers.forEach(user=>addNotification(user,`Задача «${t.title}» ожидает вашего решения`,`#tasks/${t.id}`));save();taskDialog(id);}
  if(action==="approve-task"){const t=state.tasks.find(x=>x.id===id);if(!t.approvers.includes(state.currentEmployee)||t.decisions[state.currentEmployee])return toast("Решение недоступно");t.decisions[state.currentEmployee]="approved";t.history.push({at:nowIso(),actor:state.currentEmployee,text:"Согласующий одобрил задачу"});if(t.approvers.every(user=>t.decisions[user]==="approved")){t.workflow="Выполнено";t.completedAt=nowIso();t.history.push({at:nowIso(),actor:state.currentEmployee,text:"Получены два независимых согласования. Задача выполнена"})}save();taskDialog(id);toast(t.workflow==="Выполнено"?"Получены оба согласования":"Первое решение сохранено");}
  if(action==="revision-task"){const t=state.tasks.find(x=>x.id===id);openModal(`<form class="modal-content" id="revisionForm" data-id="${id}"><span class="eyebrow">Возврат на доработку</span><h2>${esc(t.title)}</h2><label class="field"><span>Комментарий *</span><textarea name="comment" required></textarea></label><label class="field"><span>Новый дедлайн *</span><input type="datetime-local" name="deadline" min="${addDays(0).slice(0,16)}" value="${addDays(2,"17:00")}" required></label><div class="form-actions"><button class="button danger">Вернуть</button></div></form>`);}
  if(action==="chat"){state.activeChat=id;save();messages()} if(action==="message-task"){const text=target.dataset.text||"";closeModal();location.hash="tasks";taskForm(text.slice(0,120))}
  if(action==="select-employee"){state.currentEmployee=id;const chats=accessibleChats();state.activeChat=chats[0]?.id||null;save();closeModal();render();toast("Демо-профиль переключён")}
  if(action==="cancel-meeting"){const m=state.meetings.find(x=>x.id===id);m.status="Отменена";m.participants.forEach(user=>user!==state.currentEmployee&&addNotification(user,`Встреча «${m.title}» отменена`,"#calendar"));save();closeModal();calendar();toast("Встреча отменена, помещение освобождено")}
  if(action==="dismiss-employee"){const e=person(id);if(id===state.currentEmployee)return toast("Нельзя архивировать выбранный профиль");if(confirm(`Переместить ${e.name} в архив? Активные задачи будут переданы заместителю, если он указан.`)){e.archived=true;e.dismissedAt=nowIso();e.status="🔴 Не в сети";const count=autoSubstitute({...e,status:"🌴 В отпуске"});save();closeModal();employees();toast(`Сотрудник в архиве. Замен задач: ${count}`)}}
  if(action==="feed-filter"){state.feedFilter=target.dataset.filter;save();feed()} if(action==="react"){const p=state.posts.find(x=>x.id===id),key=target.dataset.reaction;Object.keys(p.reactions).forEach(k=>p.reactions[k]=p.reactions[k].filter(user=>user!==state.currentEmployee));if(!target.classList.contains("active"))p.reactions[key].push(state.currentEmployee);save();feed()}
  if(action==="edit-post")postForm(state.posts.find(p=>p.id===id)); if(action==="delete-post"&&confirm("Удалить эту публикацию?")){state.posts=state.posts.filter(p=>p.id!==id);save();feed()}
  if(action==="read-all"){state.notifications.filter(n=>n.recipient===state.currentEmployee).forEach(n=>n.read=true);save();notifications()} if(action==="open-notification"){const n=state.notifications.find(x=>x.id===id);n.read=true;save();closeModal()}
  if(action==="toggle-workday"){const session=workSession();if(session)session.endedAt=nowIso();else state.workdays.push({id:Date.now(),employee:state.currentEmployee,startedAt:nowIso(),endedAt:null});save();overview();toast(session?"Рабочий день завершён":"Таймер рабочего дня запущен")}
  if(action==="reset"&&current().role==="admin"&&confirm("Сбросить все локальные демо-данные?")){localStorage.removeItem(STORAGE_KEY);state=seedState();save();render();toast("Демо-данные сброшены")}
});
document.addEventListener("submit",event=>{if(event.target.id!=="revisionForm")return;event.preventDefault();const form=event.target,data=new FormData(form),t=state.tasks.find(x=>x.id===Number(form.dataset.id));t.workflow="На доработке";t.deadline=data.get("deadline");t.decisions[state.currentEmployee]="revision";t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Возврат на доработку: ${data.get("comment")}. Новый дедлайн: ${formatDateTime(t.deadline)}`});t.assignees.forEach(user=>addNotification(user,`Задача «${t.title}» возвращена на доработку`,`#tasks/${t.id}`));save();taskDialog(t.id);toast("Задача возвращена на доработку")});
document.addEventListener("change",event=>{if(event.target.matches("[data-action=quick-status]")){const e=current(),wasAbsent=absentStatuses.has(e.status);e.status=event.target.value;const returned=wasAbsent&&!absentStatuses.has(e.status)?restoreSubstitutions(e):0,count=autoSubstitute(e);save();overview();toast(count?`Статус обновлён. Автозамен: ${count}`:returned?`Статус обновлён. Восстановлено ролей: ${returned}`:"Статус обновлён")}});
document.addEventListener("input",event=>{if(!event.target.matches("#employeeSearch,#departmentFilter"))return;const query=$("#employeeSearch").value.toLowerCase(),department=$("#departmentFilter").value;$$('#employeeGrid [data-search]').forEach(card=>card.hidden=!card.dataset.search.includes(query)||(department&&card.dataset.department!==department))});
$("#menuButton").addEventListener("click",()=>{const open=document.body.classList.toggle("menu-open");$("#menuButton").setAttribute("aria-expanded",String(open))});
$("#menuOverlay").addEventListener("click",closeMenu);
modal.addEventListener("click",event=>{if(event.target===modal)closeModal()});
document.addEventListener("keydown",event=>{if(event.key!=="Escape")return;closeMenu();if(modal.open)closeModal()});
window.addEventListener("hashchange",()=>{closeMenu();if(modal.open)closeModal();render()});
setInterval(()=>{const timer=$("#workTimer"),session=workSession();if(timer&&session)timer.textContent=elapsed(session)},1000);
updateShell();render();
